@props(['title', 'data', 'subtitle' => ''])
@php($maximum = max([1, ...array_values($data)]))
<section class="card h-100"><div class="card-header"><h2 class="card-title">{{ $title }}</h2></div><div class="card-body">@if($subtitle)<p class="text-secondary">{{ $subtitle }}</p>@endif
@if(array_sum($data) === 0)<div class="empty-small">Aún no hay datos para esta gráfica.</div>@else<div class="stat-chart" role="img" aria-label="{{ $title }}: {{ collect($data)->map(fn($count, $label) => $label.': '.$count)->implode(', ') }}">@foreach($data as $label => $count)<div class="chart-row"><span>{{ $label }}</span><div class="chart-track"><div class="chart-fill" style="width: {{ round(($count / $maximum) * 100, 2) }}%"></div></div><strong>{{ $count }}</strong></div>@endforeach</div><table class="visually-hidden"><caption>{{ $title }}</caption><thead><tr><th>Categoría</th><th>Cantidad</th></tr></thead><tbody>@foreach($data as $label => $count)<tr><th>{{ $label }}</th><td>{{ $count }}</td></tr>@endforeach</tbody></table>@endif</div></section>
